<?php
declare(strict_types=1);
// Registered by the real native cookie/session HTTP suite; no alternate authentication path.
function auditDomain(string $scenario='TIMEOUT_AFTER_EFFECT'): array
{
    global $db,$c;$f=domainFixture($db,1,$c->config);panelBind($f);$registry=new \Hostider\Domains\Registry($db,$f['config']);$domain=$db->transaction(fn()=>$registry->attach($f['service']['id'],$f['customer'],$f['name'],$f['rule'],$f['contact'],$f['ns'],$f['actor'],\Hostider\Core\Id::uuid()));
    $engine=new \Hostider\Domains\DomainEngine($db,$f['config']);$operation=$engine->enqueueRegister($domain,$f['customer'],$f['actor'],\Hostider\Core\Id::uuid());$claim=$engine->claim($f['actor'],\Hostider\Core\Id::uuid(),$operation);$registrar=new \Hostider\Providers\Mock\DurableRegistrar($db,$f['config'],$claim['account']['id'],$scenario);$result=$registrar->execute(new \Hostider\Providers\Contract\Operation($claim['attempt_id'],'register',null,$claim['payload']['configuration']));$engine->finishAttempt($operation,$claim['lease_token'],$result,null,$f['actor'],\Hostider\Core\Id::uuid());
    return $f+compact('domain','operation','claim');
}
function auditInspect(array $f): string
{
    global $db;$db->execute('DELETE FROM rate_limits');$r=panelCommand(['action'=>'inspect','customer'=>$f['customer'],'payload'=>(object)['service_id'=>$f['service']['id'],'operation_id'=>$f['operation']]]);same(200,$r[0]);$job=$r[1]['data']['inspection_job_id'];same(1,domainCli($f,['panel:inspect'])['worked']);$row=$db->execute('SELECT status,result_id FROM panel_inspections WHERE id=?',[$job])->fetch();same('SUCCEEDED',$row['status']);return $row['result_id'];
}
function auditSummary(array $f,string $evidence,string $ctx='admin'): array{return panelHttp('/api/v1/'.$ctx.'/provider-panel/evidence?customer='.$f['customer'].'&id='.$f['service']['id'].'&operation_id='.$f['operation'].'&evidence_id='.$evidence);}
function auditResolve(array $f,string $evidence,string $outcome): array{return ['action'=>'resolve','customer'=>$f['customer'],'payload'=>(object)['service_id'=>$f['service']['id'],'operation_id'=>$f['operation'],'evidence_id'=>$evidence,'outcome'=>$outcome]];}
function auditParallel(array $d,string $confirmation): array
{
    global $server,$second,$jars,$tokens,$env;$children=[];$d['confirmation']=(object)['id'=>$confirmation,'accepted'=>true];$cookie=implode('; ',array_map(fn($k,$v)=>$k.'='.$v,array_keys($jars['admin']),$jars['admin']));
    foreach([$server,$second] as $srv){$pipes=[];$p=proc_open([PHP_BINARY,__DIR__.'/provider-panel-http-child.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,null,$env);if(!is_resource($p)){throw new RuntimeException('HTTP child unavailable');}fwrite($pipes[0],json_encode(['url'=>'http://127.0.0.1:'.$srv->diagnostics()['port'].'/api/v1/admin/provider-panel/execute','body'=>$d,'key'=>\Hostider\Core\Id::uuid(),'cookie'=>$cookie,'csrf'=>$tokens['admin']],JSON_THROW_ON_ERROR));fclose($pipes[0]);$children[]=[$p,$pipes];}
    $out=[];$bad=false;foreach($children as [$p,$pipes]){$raw=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($p);$bad=$bad||$exit!==0||$err!=='';$out[]=json_decode($raw,true,32,JSON_THROW_ON_ERROR);}same(false,$bad);return $out;
}
test('F4-F audit Domain success summary is allowlisted scoped and bound to explicit SUCCESS',function()use($db,&$examples): void{
    $f=auditDomain();$e=auditInspect($f);$r=auditSummary($f,$e);same(200,$r[0]);$s=$r[1]['data'];same('verified_success',$s['classification']);same(['CONFIRMED_SUCCESS'],$s['allowed_outcomes']);same('MOCK',$s['provenance']);same(true,$s['fresh']);same('MANUAL_REVIEW',$s['operation_state']);same(true,$s['bindings']['active_attempt']);foreach(['proof','call','contact','request_encrypted','fingerprint','lease_token','password','context','evidence_encrypted'] as $field){same(false,str_contains($r[2],'"'.$field.'"'));}same(false,str_contains($r[2],$f['contact']['email']));$d=auditResolve($f,$e,'CONFIRMED_SUCCESS');$p=panelPrepare($d,'admin');same(200,$p[0]);same($s,$p[1]['data']['plan']['evidence']);same('CONFIRMED_SUCCESS',$p[1]['data']['plan']['outcome']);same(200,panelExecute($d,$p[1]['data']['id'],'admin')[0]);same('SUCCEEDED',$db->execute('SELECT status FROM domain_operations WHERE id=?',[$f['operation']])->fetchColumn());$examples['audit-domain-success']=$s;
});
test('F4-F audit definitive no effect enables FAILURE only and never registrar failover',function()use($db,&$examples): void{
    $f=auditDomain('DEFINITIVE_FAILURE');$e=auditInspect($f);$r=auditSummary($f,$e);same(200,$r[0]);same('definitive_no_effect',$r[1]['data']['classification']);same(['CONFIRMED_FAILURE'],$r[1]['data']['allowed_outcomes']);same(true,$r[1]['data']['bindings']['financial_no_effect']);same(409,panelPrepare(auditResolve($f,$e,'CONFIRMED_SUCCESS'),'admin')[0]);$d=auditResolve($f,$e,'CONFIRMED_FAILURE');$p=panelPrepare($d,'admin');same(200,$p[0]);same('CONFIRMED_FAILURE',$p[1]['data']['plan']['outcome']);same(200,panelExecute($d,$p[1]['data']['id'],'admin')[0]);same('FAILED',$db->execute('SELECT status FROM domain_operations WHERE id=?',[$f['operation']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM domain_registrar_attempts WHERE operation_id=?',[$f['operation']])->fetchColumn());same(1,(int)$db->execute('SELECT COUNT(*) FROM mock_registrar_calls WHERE operation_id=?',[$f['claim']['attempt_id']])->fetchColumn());$examples['audit-domain-no-effect']=$r[1]['data'];
});
test('F4-F audit resource absent with uncertain money effect cannot offer definitive failure',function()use($db,&$examples): void{
    $f=auditDomain('TIMEOUT_BEFORE_EFFECT');$e=auditInspect($f);$r=auditSummary($f,$e);same(200,$r[0]);same('insufficient_evidence',$r[1]['data']['classification']);same([],$r[1]['data']['allowed_outcomes']);same(false,$r[1]['data']['bindings']['financial_no_effect']);foreach(['CONFIRMED_FAILURE','CONFIRMED_SUCCESS'] as $outcome){same(409,panelPrepare(auditResolve($f,$e,$outcome),'admin')[0]);}same('MANUAL_REVIEW',$db->execute('SELECT status FROM domain_operations WHERE id=?',[$f['operation']])->fetchColumn());same(0,(int)$db->execute('SELECT COUNT(*) FROM domain_resolutions WHERE operation_id=?',[$f['operation']])->fetchColumn());$examples['audit-domain-insufficient']=$r[1]['data'];
});
test('F4-F audit wrong customer operation and forged summary are rejected',function(): void{
    $f=auditDomain();$e=auditInspect($f);$other=auditDomain();$wrong=$other;$wrong['operation']=$f['operation'];same(404,auditSummary($wrong,$e)[0]);$d=auditResolve($f,$e,'CONFIRMED_SUCCESS');$d['payload']->summary=(object)['classification'=>'definitive_no_effect'];same(422,panelPrepare($d,'admin')[0]);
});
test('F4-F audit changed active attempt invalidates previously valid inspection',function()use($db): void{
    $f=auditDomain();$e=auditInspect($f);$other=auditDomain();$db->execute('UPDATE domain_operations SET active_attempt_id=? WHERE id=?',[$other['claim']['attempt_id'],$f['operation']]);same(409,auditSummary($f,$e)[0]);same(409,panelPrepare(auditResolve($f,$e,'CONFIRMED_SUCCESS'),'admin')[0]);
});
test('F4-F audit generation or version drift rejects summary and old confirmation',function()use($db): void{
    foreach(['generation','version'] as $field){$f=auditDomain();$e=auditInspect($f);$d=auditResolve($f,$e,'CONFIRMED_SUCCESS');$p=panelPrepare($d,'admin');same(200,$p[0]);if($field==='generation'){raises(PDOException::class,fn()=>$db->execute('UPDATE domain_operations SET generation=generation+1 WHERE id=?',[$f['operation']]));}$db->execute('UPDATE domains SET version=version+1 WHERE id=?',[$f['domain']]);same(409,auditSummary($f,$e)[0]);same(409,panelExecute($d,$p[1]['data']['id'],'admin')[0]);}
});
test('F4-F audit changed outcome and stale evidence cannot reuse explicit confirmation',function()use($db): void{
    $f=auditDomain('DEFINITIVE_FAILURE');$e=auditInspect($f);$d=auditResolve($f,$e,'CONFIRMED_FAILURE');$p=panelPrepare($d,'admin');same(200,$p[0]);$tampered=auditResolve($f,$e,'CONFIRMED_SUCCESS');same(403,panelExecute($tampered,$p[1]['data']['id'],'admin')[0]);$old=$db->execute('SELECT * FROM domain_inspections WHERE id=?',[$e])->fetch();$stale=\Hostider\Core\Id::uuid();$crypto=new \Hostider\Core\Security\Crypto(base64_decode($f['config']->key,true));$plain=$crypto->decrypt($old['evidence_encrypted'],'domain-inspect:'.$e);$db->execute('INSERT INTO domain_inspections(id,operation_id,attempt_id,actor_id,found,evidence_encrypted,fingerprint,created_at) VALUES (?,?,?,?,?,?,?,DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 6 MINUTE))',[$stale,$old['operation_id'],$old['attempt_id'],$old['actor_id'],$old['found'],$crypto->encrypt($plain,'domain-inspect:'.$stale),$old['fingerprint']]);same(409,auditSummary($f,$stale)[0]);same(409,panelPrepare(auditResolve($f,$stale,'CONFIRMED_FAILURE'),'admin')[0]);same(403,panelExecute(auditResolve($f,$stale,'CONFIRMED_FAILURE'),$p[1]['data']['id'],'admin')[0]);
});
test('F4-F audit Cloud pending task has no success or failure outcome',function()use($db,&$examples): void{
    $f=panelCloud();$f['operation']=cloudAction($f,'STOP');same(true,(new \Hostider\Cloud\Worker($db,$f['config'],'TIMEOUT_AFTER_EFFECT'))->once($f['operation']));$e=auditInspect($f);$r=auditSummary($f,$e);same(200,$r[0]);same('pending',$r[1]['data']['classification']);same([],$r[1]['data']['allowed_outcomes']);same(false,$r[1]['data']['failure_supported']);same(409,panelPrepare(auditResolve($f,$e,'CONFIRMED_SUCCESS'),'admin')[0]);same(409,panelPrepare(auditResolve($f,$e,'CONFIRMED_FAILURE'),'admin')[0]);same('UNKNOWN',$db->execute('SELECT status FROM cloud_operations WHERE id=?',[$f['operation']])->fetchColumn());$examples['audit-cloud-pending']=$r[1]['data'];
});
test('F4-F audit evidence requires both exact staff permissions and rejects customer',function()use($db,$admin): void{
    $f=auditDomain();panelSelect($f);$e=auditInspect($f);same(403,auditSummary($f,$e,'client')[0]);$assignment=$db->execute('SELECT id FROM identity_assignments WHERE user_id=? AND customer_id IS NULL',[$admin['user']])->fetchColumn();foreach(['services.reconcile','services.manage'] as $permission){$rows=$db->execute('SELECT * FROM identity_grants WHERE assignment_id=? AND permission=? AND customer_scope=? AND service_scope=?',[$assignment,$permission,$f['customer'],$f['service']['id']])->fetchAll();$db->execute('DELETE FROM identity_grants WHERE assignment_id=? AND permission=? AND customer_scope=? AND service_scope=?',[$assignment,$permission,$f['customer'],$f['service']['id']]);try{same(403,auditSummary($f,$e)[0]);}finally{foreach($rows as $r){$db->execute('INSERT INTO identity_grants(id,assignment_id,permission,customer_scope,service_scope,department_scope) VALUES (?,?,?,?,?,?)',[$r['id'],$r['assignment_id'],$r['permission'],$r['customer_scope'],$r['service_scope'],$r['department_scope']]);}}}
});
test('F4-F audit foreign Cloud task and later instance generation cannot produce success',function()use($db): void{
    $f=panelCloud();$f['operation']=cloudAction($f,'STOP');same(true,(new \Hostider\Cloud\Worker($db,$f['config'],'TIMEOUT_AFTER_EFFECT'))->once($f['operation']));$e=auditInspect($f);$db->execute('UPDATE cloud_operations SET task_id=? WHERE id=?',[\Hostider\Core\Id::uuid(),$f['operation']]);$r=auditSummary($f,$e);same(200,$r[0]);same('mismatch',$r[1]['data']['classification']);same([],$r[1]['data']['allowed_outcomes']);same(false,$r[1]['data']['bindings']['task_account_resource']);same(409,panelPrepare(auditResolve($f,$e,'CONFIRMED_SUCCESS'),'admin')[0]);$db->execute('UPDATE cloud_instances SET generation=generation+1,version=version+1 WHERE id=?',[$f['instance']]);same(409,auditSummary($f,$e)[0]);same(0,(int)$db->execute('SELECT COUNT(*) FROM cloud_effects WHERE operation_id=?',[$f['operation']])->fetchColumn());
});
test('F4-F audit parallel HTTP confirmation applies exactly one reconciliation and replay no effect',function()use($db): void{
    $f=auditDomain();$e=auditInspect($f);$d=auditResolve($f,$e,'CONFIRMED_SUCCESS');$p=panelPrepare($d,'admin');same(200,$p[0]);$r=auditParallel($d,$p[1]['data']['id']);$statuses=array_column($r,'status');sort($statuses);same([200,409],$statuses);same(1,(int)$db->execute('SELECT COUNT(*) FROM domain_resolutions WHERE operation_id=?',[$f['operation']])->fetchColumn());same(409,panelExecute($d,$p[1]['data']['id'],'admin')[0]);same(1,(int)$db->execute('SELECT COUNT(*) FROM domain_evidence WHERE operation_id=?',[$f['operation']])->fetchColumn());
});
